CREATE OR REPLACE FUNCTION private.guard_profile_deletion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF current_user='authenticated' THEN
  IF OLD.id=auth.uid() OR OLD.role::text='CEO' OR NOT private.has_permission(auth.uid(),'admin.users.edit') THEN RAISE EXCEPTION 'Protected account cannot be deleted'; END IF;
  PERFORM pg_advisory_xact_lock(734918206);
  IF OLD.role::text='SUPER_ADMIN' AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id<>OLD.id AND p.role::text='SUPER_ADMIN' AND p.is_active AND private.has_permission(p.id,'admin.users.edit')) THEN RAISE EXCEPTION 'Keep one active Super Admin'; END IF;
 END IF;
 RETURN OLD;
END $function$

CREATE OR REPLACE FUNCTION private.guard_profile_authorization()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF current_user='authenticated' THEN
  IF TG_OP='INSERT' AND NOT private.has_permission(auth.uid(),'admin.users.edit') THEN RAISE EXCEPTION 'User administration permission required'; END IF;
  IF TG_OP='UPDATE' THEN
   IF NEW.id<>auth.uid() AND NOT private.has_permission(auth.uid(),'admin.users.edit') THEN RAISE EXCEPTION 'User administration permission required'; END IF;
   IF (NEW.role IS DISTINCT FROM OLD.role OR NEW.is_active IS DISTINCT FROM OLD.is_active OR NEW.is_email_verified IS DISTINCT FROM OLD.is_email_verified OR NEW.must_reset_password IS DISTINCT FROM OLD.must_reset_password OR NEW.mfa_enabled IS DISTINCT FROM OLD.mfa_enabled OR NEW.mfa_secret_encrypted IS DISTINCT FROM OLD.mfa_secret_encrypted) THEN
    IF NEW.id=auth.uid() OR OLD.role::text='CEO' OR NOT private.has_permission(auth.uid(),'admin.users.edit') THEN RAISE EXCEPTION 'Authorization fields are protected'; END IF;
    PERFORM pg_advisory_xact_lock(734918206);
    IF OLD.role::text='SUPER_ADMIN' AND (NEW.role::text<>'SUPER_ADMIN' OR NOT NEW.is_active) AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id<>OLD.id AND p.role::text='SUPER_ADMIN' AND p.is_active AND private.has_permission(p.id,'admin.users.edit')) THEN RAISE EXCEPTION 'Keep one active Super Admin'; END IF;
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.provision_auth_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE profile_role public.user_role; c public.contractors;
BEGIN
 IF NEW.email IS NULL THEN RETURN NEW; END IF;
 profile_role:=CASE WHEN NEW.raw_app_meta_data->>'role' IN ('CEO','SUPER_ADMIN','ADMIN','CONTRACTOR')
  THEN (NEW.raw_app_meta_data->>'role')::public.user_role ELSE 'CONTRACTOR'::public.user_role END;
 IF TG_OP='INSERT' THEN
  INSERT INTO public.profiles(id,email,first_name,last_name,role,is_active,is_email_verified,must_reset_password)
  VALUES(NEW.id,NEW.email,coalesce(NEW.raw_user_meta_data->>'first_name',''),coalesce(NEW.raw_user_meta_data->>'last_name',''),profile_role,true,NEW.email_confirmed_at IS NOT NULL,profile_role::text='CONTRACTOR')
  ON CONFLICT(id) DO NOTHING;
 ELSE
  UPDATE public.profiles SET email=NEW.email,is_email_verified=(NEW.email_confirmed_at IS NOT NULL)
  WHERE id=NEW.id AND (email IS DISTINCT FROM NEW.email OR is_email_verified IS DISTINCT FROM (NEW.email_confirmed_at IS NOT NULL));
 END IF;
 IF profile_role::text='CONTRACTOR' AND NEW.raw_app_meta_data ? 'contractor_record_id' THEN
  SELECT * INTO c FROM public.contractors WHERE id::text=NEW.raw_app_meta_data->>'contractor_record_id' FOR UPDATE;
  IF c.id IS NULL OR c.is_deleted OR lower(c.business_email) IS DISTINCT FROM lower(NEW.email)
   OR (c.profile_id IS NOT NULL AND c.profile_id<>NEW.id) THEN
   RAISE EXCEPTION 'Account does not match the contractor record' USING ERRCODE='42501'; END IF;
  IF NEW.email_confirmed_at IS NOT NULL AND c.profile_id IS NULL THEN
   UPDATE public.contractors SET profile_id=NEW.id WHERE id=c.id;
   UPDATE public.profiles SET first_name=c.first_name,last_name=c.last_name,phone=c.business_phone WHERE id=NEW.id;
   INSERT INTO public.audit_logs(action,entity_type,entity_id,user_id,user_role,new_values,change_summary)
   VALUES('CONTRACTOR_ACCOUNT_VERIFIED','contractor',c.id,NEW.id,'CONTRACTOR',jsonb_build_object('profile_id',NEW.id),'Contractor verified email ownership');
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.enforce_max_two_super_admins()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.role::text = 'SUPER_ADMIN' THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(734918205);
    IF (SELECT count(*) FROM public.profiles
        WHERE role::text = 'SUPER_ADMIN' AND id <> NEW.id) >= 2 THEN
      RAISE EXCEPTION 'Cannot assign SUPER_ADMIN role: limit of two reached.';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.has_permission(p_profile_id uuid, p_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; active boolean; def boolean; privileged boolean; effect text; permitted boolean;
BEGIN
 SELECT role::text,(is_active AND NOT must_reset_password) INTO r,active FROM public.profiles WHERE id=p_profile_id;
 IF NOT coalesce(active,false) OR r NOT IN ('CEO','SUPER_ADMIN','ADMIN') THEN RETURN false; END IF;
 IF r='ADMIN' AND p_key NOT IN ('admin.tickets.view','admin.tickets.edit','admin.assessments.view','admin.assessments.edit') THEN RETURN false; END IF;
 SELECT admin_default,c.privileged INTO def,privileged FROM private.permission_catalog c WHERE permission_key=p_key;
 IF NOT FOUND OR (privileged AND r NOT IN ('CEO','SUPER_ADMIN')) THEN RETURN false; END IF;
 SELECT u.effect INTO effect FROM public.user_permissions u WHERE profile_id=p_profile_id AND permission_key=p_key;
 permitted:=CASE WHEN effect IS NOT NULL THEN effect='allow' WHEN r IN ('CEO','SUPER_ADMIN','ADMIN') THEN true ELSE def END;
 IF p_key LIKE '%.edit' THEN permitted:=permitted AND private.has_permission(p_profile_id,regexp_replace(p_key,'\.edit$','.view')); END IF;
 RETURN coalesce(permitted,false);
END $function$

CREATE OR REPLACE FUNCTION private.compute_vehicle_claim_amount()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  shift_hours numeric;
  rate numeric(10,2); shift_record public.time_entries;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.time_entries t
    WHERE t.id=NEW.time_entry_id AND t.contractor_id=NEW.contractor_id
      AND (t.contractor_role='DRIVER' OR t.vehicle_minutes>0)) THEN
    RAISE EXCEPTION 'Vehicle claim requires the same contractor and a driver shift';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.vehicle_photo_url IS NULL OR NEW.license_plate_photo_url IS NULL
       OR NEW.vehicle_photo_url NOT LIKE NEW.contractor_id::text||'/time-entries/'||NEW.time_entry_id::text||'/%'
       OR NEW.license_plate_photo_url NOT LIKE NEW.contractor_id::text||'/time-entries/'||NEW.time_entry_id::text||'/%' THEN
      RAISE EXCEPTION 'Vehicle photos must belong to this contractor shift';
    END IF;
    IF NEW.vehicle_photo_url = NEW.license_plate_photo_url THEN
      RAISE EXCEPTION 'Upload distinct vehicle and license-plate photos';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id='time-entry-photos' AND name=NEW.vehicle_photo_url)
       OR NOT EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id='time-entry-photos' AND name=NEW.license_plate_photo_url) THEN
      RAISE EXCEPTION 'Upload both vehicle and license-plate photos before submitting the claim';
    END IF;
    IF NEW.status <> 'PENDING' OR NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL OR NEW.rejection_reason IS NOT NULL THEN
      RAISE EXCEPTION 'New vehicle claims must await administrator review';
    END IF;
  ELSE
    IF ROW(NEW.time_entry_id,NEW.contractor_id,NEW.vehicle_type,NEW.declared_hours,NEW.notes,NEW.vehicle_photo_url,NEW.license_plate_photo_url)
       IS DISTINCT FROM ROW(OLD.time_entry_id,OLD.contractor_id,OLD.vehicle_type,OLD.declared_hours,OLD.notes,OLD.vehicle_photo_url,OLD.license_plate_photo_url) THEN
      RAISE EXCEPTION 'Submitted vehicle claim details are immutable';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      IF private.active_profile_role() NOT IN ('SUPER_ADMIN','CEO') OR private.active_profile_role() IS NULL OR NOT private.has_permission(auth.uid(),'admin.payroll.edit') THEN
        RAISE EXCEPTION 'Administrator review required';
      END IF;
      IF OLD.status <> 'PENDING' OR NEW.status NOT IN ('APPROVED','REJECTED') THEN
        RAISE EXCEPTION 'Vehicle claim has already been reviewed';
      END IF;
      IF NEW.status='REJECTED' AND length(trim(coalesce(NEW.rejection_reason,'')))=0 THEN
        RAISE EXCEPTION 'Rejection reason required';
      END IF;
      NEW.reviewed_by := auth.uid();
      NEW.reviewed_at := clock_timestamp();
    ELSE
      NEW.reviewed_by := OLD.reviewed_by;
      NEW.reviewed_at := OLD.reviewed_at;
      NEW.rejection_reason := OLD.rejection_reason;
    END IF;
    NEW.amount := OLD.amount;
    NEW.capped := OLD.capped;
    RETURN NEW;
  END IF;
  SELECT * INTO shift_record FROM public.time_entries WHERE id=NEW.time_entry_id AND clock_out_at IS NOT NULL;
  IF shift_record.calculation_version='AGREEMENT' THEN
    shift_hours:=shift_record.vehicle_minutes/60;
    IF shift_hours IS NULL OR shift_hours<=0 THEN RAISE EXCEPTION 'Record vehicle-use intervals before claiming an allowance'; END IF;
    NEW.declared_hours:=shift_hours; NEW.amount:=shift_record.vehicle_allowance_amount; NEW.capped:=false;
    RETURN NEW;
  END IF;
  shift_hours:=greatest(extract(epoch FROM shift_record.clock_out_at-shift_record.clock_in_at)/3600-coalesce(shift_record.break_minutes,0)/60,0);
  rate:=shift_record.legacy_vehicle_rate_applied;
  IF rate IS NULL THEN RAISE EXCEPTION 'No historical vehicle allowance is configured'; END IF;
  IF shift_hours IS NULL THEN
    RAISE EXCEPTION 'Vehicle reimbursement can only be finalized after the time entry is closed.';
  END IF;

  IF NEW.declared_hours > shift_hours THEN
    NEW.declared_hours := shift_hours;
    NEW.capped := true;
  ELSE
    NEW.capped := false;
  END IF;

  NEW.amount := ROUND(NEW.declared_hours * rate, 2);
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.set_user_permissions(p_profile_id uuid, p_overrides jsonb, p_version uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); target_role text; old_values jsonb; old_version uuid; entry record;
BEGIN
 IF actor IS NULL OR NOT private.has_permission(actor,'admin.users.edit') THEN RAISE EXCEPTION 'Super Admin permission required' USING ERRCODE='42501'; END IF;
 IF actor=p_profile_id THEN RAISE EXCEPTION 'You cannot change your own permissions' USING ERRCODE='42501'; END IF;
 -- Serialize permission and account edits, including concurrent last-admin changes.
 PERFORM pg_advisory_xact_lock(734918206);
 IF NOT private.has_permission(actor,'admin.users.edit') THEN RAISE EXCEPTION 'Super Admin permission required' USING ERRCODE='42501'; END IF;
 SELECT role::text INTO target_role FROM public.profiles WHERE id=p_profile_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'User not found' USING ERRCODE='P0002'; END IF;
 IF target_role NOT IN ('ADMIN','SUPER_ADMIN') THEN RAISE EXCEPTION 'Contractor and executive permissions are locked' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(p_overrides) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Overrides must be an object' USING ERRCODE='22023'; END IF;
 FOR entry IN SELECT key,value FROM jsonb_each_text(p_overrides) LOOP
  IF NOT EXISTS(SELECT 1 FROM private.permission_catalog WHERE permission_key=entry.key) OR entry.value NOT IN ('allow','deny') OR entry.value IS NULL THEN RAISE EXCEPTION 'Unknown permission or effect' USING ERRCODE='22023'; END IF;
  IF entry.key LIKE '%.edit' AND entry.value='allow' AND p_overrides->>regexp_replace(entry.key,'\.edit$','.view')='deny' THEN RAISE EXCEPTION 'Enable View before Edit' USING ERRCODE='22023'; END IF;
  IF entry.key LIKE 'admin.users.%' AND entry.value='allow' AND target_role<>'SUPER_ADMIN' THEN RAISE EXCEPTION 'User administration requires the Super Admin role' USING ERRCODE='42501'; END IF;
 END LOOP;
 SELECT version INTO old_version FROM public.user_permission_versions WHERE profile_id=p_profile_id;
 IF old_version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'Permissions changed. Reload before saving.' USING ERRCODE='40001'; END IF;
 SELECT coalesce(jsonb_object_agg(permission_key,effect),'{}'::jsonb) INTO old_values FROM public.user_permissions WHERE profile_id=p_profile_id;
 DELETE FROM public.user_permissions WHERE profile_id=p_profile_id;
 INSERT INTO public.user_permissions(profile_id,permission_key,effect,updated_by) SELECT p_profile_id,key,value,actor FROM jsonb_each_text(p_overrides);
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE role::text='SUPER_ADMIN' AND is_active AND private.has_permission(id,'admin.users.edit')) THEN RAISE EXCEPTION 'Keep at least one active Super Admin with user administration' USING ERRCODE='42501'; END IF;
 INSERT INTO public.user_permission_versions(profile_id) VALUES(p_profile_id) ON CONFLICT(profile_id) DO UPDATE SET version=gen_random_uuid();
 INSERT INTO public.audit_logs(action,entity_type,entity_id,user_id,user_role,old_values,new_values,change_summary)
 VALUES('PERMISSIONS_UPDATED','user_permissions',p_profile_id,actor,'SUPER_ADMIN',old_values,p_overrides,'Individual admin permissions updated');
 RETURN private.user_permission_settings(p_profile_id);
END $function$

CREATE OR REPLACE FUNCTION private.privileged_payroll_entries(p_from timestamp with time zone, p_to timestamp with time zone, p_storm uuid, p_contractor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;
BEGIN
 IF auth.uid() IS NULL OR private.active_profile_role() NOT IN ('CEO','SUPER_ADMIN') OR NOT private.has_permission(auth.uid(),'admin.payroll.view') THEN RAISE EXCEPTION 'Confidential payroll access denied' USING ERRCODE='42501'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'contractor_id',contractor_id,'status',status,'total_minutes',extract(epoch FROM clock_out_at-clock_in_at)/60,'billable_minutes',coalesce(paid_minutes_exact,billable_minutes),'payroll_amount',payroll_amount,'utility_bill_amount',utility_bill_amount)),'[]') INTO result FROM public.time_entries
 WHERE is_deleted IS NOT TRUE AND clock_out_at IS NOT NULL AND status<>'REJECTED' AND (p_from IS NULL OR clock_in_at>=p_from) AND (p_to IS NULL OR clock_in_at<=p_to) AND (p_storm IS NULL OR storm_event_id=p_storm) AND (p_contractor IS NULL OR contractor_id=p_contractor);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION private.guard_pay_agreement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE previous jsonb; actor_id uuid:=auth.uid(); actor text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Pay agreements are immutable; create a new effective version' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.contractor_id::text,0));
 IF actor_id IS NULL AND current_setting('role',true)='service_role' THEN actor_id:=NEW.created_by; END IF;
 SELECT role::text INTO actor FROM public.profiles WHERE id=actor_id;
 IF actor_id IS NULL OR actor NOT IN ('CEO','SUPER_ADMIN') OR NOT private.has_permission(actor_id,'admin.payroll.edit') THEN
  RAISE EXCEPTION 'Privileged payroll editing required' USING ERRCODE='42501'; END IF;
 PERFORM private.validate_compensation(NEW.terms);
 IF NOT isfinite(NEW.effective_from) OR NEW.effective_from<clock_timestamp()-interval '1 minute' OR EXISTS(SELECT 1 FROM public.time_entries WHERE contractor_id=NEW.contractor_id AND clock_out_at>=NEW.effective_from) THEN
  RAISE EXCEPTION 'Use a current or future effective time outside closed payroll' USING ERRCODE='23514'; END IF;
 SELECT terms INTO previous FROM public.contractor_pay_agreements WHERE contractor_id=NEW.contractor_id AND effective_from<NEW.effective_from ORDER BY effective_from DESC LIMIT 1;
 IF previous IS NOT NULL AND ROW(previous->>'timezone',previous->>'week_start_day') IS DISTINCT FROM ROW(NEW.terms->>'timezone',NEW.terms->>'week_start_day') THEN
  IF private.pay_week_start(NEW.effective_from,previous)<>NEW.effective_from THEN
   RAISE EXCEPTION 'Workweek changes require the current workweek boundary' USING ERRCODE='23514'; END IF;
 END IF;
 NEW.created_by:=actor_id; NEW.created_at:=clock_timestamp();
 INSERT INTO public.audit_logs(action,entity_type,entity_id,user_id,user_role,old_values,new_values,change_summary)
 VALUES('PAY_AGREEMENT_CREATED','contractor',NEW.contractor_id,actor_id,actor::public.user_role,previous,to_jsonb(NEW),'Effective contractor pay agreement saved');
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.guard_internal_account_creation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c public.contractors; setup_claim private.contractor_account_setup_claims;
BEGIN
 IF NEW.raw_app_meta_data->>'role' IN ('CEO','SUPER_ADMIN','ADMIN') THEN RETURN NEW; END IF;
 IF NEW.email IS NULL THEN RAISE EXCEPTION 'Internally added contractor required' USING ERRCODE='42501'; END IF;
 -- Supabase Auth may insert a user before persisting server-only app_metadata.
 -- A high-entropy, one-use claim from the protected setup RPC authorizes only
 -- this exact pre-added email/contractor pair for a short window.
 IF NEW.raw_user_meta_data ? 'contractor_setup_claim_token' THEN
  SELECT sc.* INTO setup_claim FROM private.contractor_account_setup_claims sc
  JOIN public.contractors co ON co.id=sc.contractor_id
  WHERE sc.claim_token::text=NEW.raw_user_meta_data->>'contractor_setup_claim_token'
   AND sc.contractor_id::text=NEW.raw_user_meta_data->>'contractor_record_id'
   AND sc.consumed_at IS NULL AND sc.expires_at>clock_timestamp()
   AND co.profile_id IS NULL AND co.is_deleted IS NOT TRUE
   AND lower(co.business_email)=lower(NEW.email)
  FOR UPDATE OF sc,co;
  IF setup_claim.contractor_id IS NULL THEN RAISE EXCEPTION 'Valid contractor setup request required' USING ERRCODE='42501'; END IF;
  UPDATE private.contractor_account_setup_claims SET consumed_at=clock_timestamp() WHERE contractor_id=setup_claim.contractor_id;
  RETURN NEW;
 END IF;
 -- Preserve service-created contractor accounts whose trusted app metadata is
 -- already present during INSERT.
 IF NEW.raw_app_meta_data->>'role' IS DISTINCT FROM 'CONTRACTOR' THEN
  RAISE EXCEPTION 'Internally added contractor required' USING ERRCODE='42501';
 END IF;
 SELECT * INTO c FROM public.contractors WHERE id::text=NEW.raw_app_meta_data->>'contractor_record_id' FOR UPDATE;
 IF c.id IS NULL OR c.profile_id IS NOT NULL OR c.is_deleted OR lower(c.business_email) IS DISTINCT FROM lower(NEW.email)
  OR c.account_setup_requested_at IS NULL OR c.account_setup_requested_at<clock_timestamp()-interval '10 minutes' THEN
  RAISE EXCEPTION 'Valid contractor setup request required' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM auth.users WHERE lower(email)=lower(NEW.email)) THEN
  RAISE EXCEPTION 'Account already exists' USING ERRCODE='23505'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.guard_field_assessment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); role_name text:=private.active_profile_role(); t public.tickets; BEGIN
 IF actor IS NULL OR role_name IS NULL OR NOT private.contractor_portal_ready() THEN RAISE EXCEPTION 'Active signed-in profile required' USING ERRCODE='42501'; END IF;
 SELECT * INTO t FROM public.tickets WHERE id=NEW.ticket_id FOR UPDATE;
 IF TG_OP='UPDATE' THEN
 IF (to_jsonb(NEW)-ARRAY['review_stage','team_reviewed_by','team_reviewed_at','team_review_notes','reviewed_by','reviewed_at','review_notes','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['review_stage','team_reviewed_by','team_reviewed_at','team_review_notes','reviewed_by','reviewed_at','review_notes','updated_at','updated_by']) THEN RAISE EXCEPTION 'Submitted assessment evidence is immutable' USING ERRCODE='23514'; END IF;
 IF NOT private.has_permission(actor,'admin.assessments.edit') OR NOT private.can_access_ticket(t.id) THEN RAISE EXCEPTION 'Ticket review permission required' USING ERRCODE='42501'; END IF;
 IF OLD.review_stage='TEAM_LEAD_REVIEW' AND NEW.review_stage IN ('FINAL_REVIEW','NEEDS_REWORK') THEN
 IF role_name IS DISTINCT FROM 'ADMIN' OR t.team_lead_id IS DISTINCT FROM actor THEN RAISE EXCEPTION 'Only the assigned team lead can review' USING ERRCODE='42501'; END IF;
 NEW.team_reviewed_by:=actor; NEW.team_reviewed_at:=now(); NEW.reviewed_by:=NULL; NEW.reviewed_at:=NULL; NEW.review_notes:=NULL;
 ELSIF OLD.review_stage='FINAL_REVIEW' AND NEW.review_stage IN ('APPROVED','NEEDS_REWORK') AND role_name IN ('CEO','SUPER_ADMIN') THEN NEW.reviewed_by:=actor; NEW.reviewed_at:=now();
 ELSE RAISE EXCEPTION 'Invalid review stage or reviewer' USING ERRCODE='42501'; END IF;
 NEW.updated_by:=actor; NEW.updated_at:=now(); RETURN NEW;
 END IF;
 IF NOT private.can_assess_ticket(t.id) OR t.assigned_to IS DISTINCT FROM NEW.contractor_id OR t.status::text NOT IN ('ON_SITE','IN_PROGRESS','NEEDS_REWORK') THEN RAISE EXCEPTION 'Assessment requires the assigned on-site ticket' USING ERRCODE='42501'; END IF;
 PERFORM private.assert_ticket_evidence(t.id,NEW.field_assessment,NEW.photo_evidence,true);
 NEW.assessed_by:=actor; NEW.created_by:=actor; NEW.updated_by:=actor; NEW.assessed_at:=now(); NEW.created_at:=now(); NEW.updated_at:=now();
 NEW.reviewed_by:=NULL; NEW.reviewed_at:=NULL; NEW.review_notes:=NULL; NEW.team_reviewed_by:=NULL; NEW.team_reviewed_at:=NULL; NEW.team_review_notes:=NULL; NEW.review_stage:='TEAM_LEAD_REVIEW';
 NEW.priority:=CASE WHEN NEW.field_assessment->'answers'->'publicDanger'='true'::jsonb OR NEW.field_assessment->'answers'->'oilLeak'='true'::jsonb THEN 'A'::public.priority_level ELSE 'C'::public.priority_level END;
 NEW.safety_observations:=jsonb_build_object('downed_conductors',NEW.field_assessment->'answers'->'conductorBroken','damaged_insulators',NEW.field_assessment->'answers'->'insulatorsBroken','vegetation_contact',NEW.field_assessment->'answers'->'treeCrewsNeeded','structural_damage',NEW.field_assessment->'answers'->'poleBroken','public_accessible',NEW.field_assessment->'answers'->'publicDanger','fire_hazard',false,'safe_distance_maintained',false);
 NEW.sync_status:='SYNCED'; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.assign_ticket_team_lead(p_ticket_id uuid, p_team_lead_id uuid)
 RETURNS tickets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE t public.tickets; BEGIN
 IF private.active_profile_role() NOT IN ('CEO','SUPER_ADMIN') OR NOT private.has_permission(auth.uid(),'admin.tickets.edit') OR NOT private.can_access_ticket(p_ticket_id) THEN RAISE EXCEPTION 'Storm manager ticket permission required' USING ERRCODE='42501'; END IF;
 SELECT * INTO t FROM public.tickets WHERE id=p_ticket_id FOR UPDATE;
 IF t.status::text NOT IN ('DRAFT','ASSIGNED','NEEDS_REWORK') OR EXISTS(SELECT 1 FROM public.ticket_assessment_drafts WHERE ticket_id=t.id) THEN RAISE EXCEPTION 'Do not reassign a ticket with active fieldwork or a saved draft' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_team_lead_id AND role='ADMIN' AND is_active AND NOT must_reset_password) THEN RAISE EXCEPTION 'Choose an active Admin team lead' USING ERRCODE='23514'; END IF;
 IF t.team_lead_id=p_team_lead_id THEN RETURN t; END IF;
 UPDATE public.tickets SET team_lead_id=p_team_lead_id,crew_id=NULL,assigned_to=NULL,assigned_driver_id=NULL,status='DRAFT',updated_by=auth.uid() WHERE id=t.id RETURNING * INTO t;
 PERFORM private.notify_ticket_user(p_team_lead_id,t.id,'Dispatch ticket '||t.ticket_number,'Assign this ticket to one of your driver/assessor crews.','ticket:'||t.id||':lead:'||p_team_lead_id||':'||t.updated_at);
 RETURN t; END $function$

CREATE OR REPLACE FUNCTION private.record_ticket_utility_handoff(p_ticket_id uuid, p_reference text)
 RETURNS tickets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE t public.tickets; BEGIN
 IF private.active_profile_role() NOT IN ('CEO','SUPER_ADMIN') OR NOT private.has_permission(auth.uid(),'admin.tickets.edit') OR NOT private.can_access_ticket(p_ticket_id) THEN RAISE EXCEPTION 'Storm manager ticket permission required' USING ERRCODE='42501'; END IF;
 IF p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'Enter the utility handoff reference or delivery notes' USING ERRCODE='23514'; END IF;
 SELECT * INTO t FROM public.tickets WHERE id=p_ticket_id FOR UPDATE;
 IF t.review_stage='UTILITY_SUBMITTED' THEN RETURN t; END IF;
 IF t.status<>'APPROVED' OR t.review_stage<>'APPROVED' OR NOT EXISTS(SELECT 1 FROM public.damage_assessments WHERE id=t.current_assessment_id AND review_stage='APPROVED') THEN RAISE EXCEPTION 'Final approval is required before utility handoff' USING ERRCODE='23514'; END IF;
 UPDATE public.tickets SET review_stage='UTILITY_SUBMITTED',status='CLOSED',utility_submitted_at=now(),utility_submitted_by=auth.uid(),utility_submission_reference=btrim(p_reference),updated_by=auth.uid() WHERE id=t.id RETURNING * INTO t;
 INSERT INTO public.audit_logs(action,entity_type,entity_id,user_id,user_role,new_values,change_summary) VALUES('UTILITY_HANDOFF_RECORDED','ticket',t.id,auth.uid(),private.active_profile_role()::public.user_role,jsonb_build_object('reference',btrim(p_reference),'assessment_id',t.current_assessment_id),'Approved ticket PDF handed to utility'); RETURN t; END $function$

CREATE OR REPLACE FUNCTION private.review_ticket_assessment(p_assessment_id uuid, p_decision text, p_notes text DEFAULT ''::text)
 RETURNS damage_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE t public.tickets; a public.damage_assessments; recipient uuid; next_stage text; BEGIN
 IF p_decision IS NULL OR p_notes IS NULL OR p_decision NOT IN ('APPROVED','NEEDS_REWORK') OR length(p_notes)>4000 OR (p_decision='NEEDS_REWORK' AND length(btrim(p_notes))=0) THEN RAISE EXCEPTION 'Choose a valid decision and include correction notes' USING ERRCODE='23514'; END IF;
 SELECT t0.* INTO t FROM public.tickets t0 JOIN public.damage_assessments a0 ON a0.ticket_id=t0.id WHERE a0.id=p_assessment_id FOR UPDATE OF t0;
 IF NOT private.can_access_ticket(t.id) OR NOT private.has_permission(auth.uid(),'admin.assessments.edit') THEN RAISE EXCEPTION 'Ticket review permission required' USING ERRCODE='42501'; END IF;
 SELECT * INTO a FROM public.damage_assessments WHERE id=p_assessment_id FOR UPDATE;
 IF t.current_assessment_id IS DISTINCT FROM a.id OR t.status<>'PENDING_REVIEW' OR t.review_stage<>a.review_stage THEN RAISE EXCEPTION 'Review the current pending assessment' USING ERRCODE='23514'; END IF;
 next_stage:=CASE WHEN p_decision='NEEDS_REWORK' THEN 'NEEDS_REWORK' WHEN a.review_stage='TEAM_LEAD_REVIEW' THEN 'FINAL_REVIEW' ELSE 'APPROVED' END;
 UPDATE public.damage_assessments SET review_stage=next_stage,team_review_notes=CASE WHEN a.review_stage='TEAM_LEAD_REVIEW' THEN '['||p_decision||'] '||btrim(p_notes) ELSE team_review_notes END,review_notes=CASE WHEN a.review_stage='FINAL_REVIEW' THEN '['||p_decision||'] '||btrim(p_notes) ELSE review_notes END WHERE id=a.id RETURNING * INTO a;
 UPDATE public.tickets SET review_stage=CASE WHEN next_stage='NEEDS_REWORK' THEN 'CORRECTIONS' ELSE next_stage END,status=CASE WHEN next_stage='NEEDS_REWORK' THEN 'NEEDS_REWORK'::public.ticket_status WHEN next_stage='APPROVED' THEN 'APPROVED'::public.ticket_status ELSE 'PENDING_REVIEW'::public.ticket_status END,updated_by=auth.uid() WHERE id=t.id;
 IF next_stage='FINAL_REVIEW' THEN FOR recipient IN SELECT id FROM public.profiles WHERE role IN ('CEO','SUPER_ADMIN') AND is_active AND NOT must_reset_password LOOP
 PERFORM private.notify_ticket_user(recipient,t.id,'Final review: ticket '||t.ticket_number,'The team lead approved the assessment. Final approval is required before utility handoff.','assessment:'||a.id||':final:'||recipient); END LOOP;
 ELSE FOR recipient IN SELECT DISTINCT profile_id FROM public.contractors WHERE id IN(t.assigned_to,t.assigned_driver_id) AND profile_id IS NOT NULL UNION SELECT t.team_lead_id LOOP
 PERFORM private.notify_ticket_user(recipient,t.id,CASE WHEN next_stage='NEEDS_REWORK' THEN 'Corrections: ticket ' ELSE 'Approved: ticket ' END||t.ticket_number,CASE WHEN next_stage='NEEDS_REWORK' THEN btrim(p_notes) ELSE 'Final approval is complete. The storm manager can export and record utility handoff.' END,'assessment:'||a.id||':'||next_stage||':'||recipient); END LOOP; END IF;
 INSERT INTO public.audit_logs(action,entity_type,entity_id,user_id,user_role,new_values,change_summary) VALUES('TICKET_ASSESSMENT_REVIEW','ticket',t.id,auth.uid(),private.active_profile_role()::public.user_role,jsonb_build_object('assessment_id',a.id,'stage',next_stage,'notes',btrim(p_notes)),'Assessment reviewed through the ticket workflow');
 RETURN a;
END $function$

CREATE OR REPLACE FUNCTION private.record_ticket_work_note(p_id uuid, p_ticket_id uuid, p_kind text, p_body text, p_reported_at timestamp with time zone)
 RETURNS ticket_work_notes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.tickets; n public.ticket_work_notes; recipient uuid; actor uuid:=auth.uid();
BEGIN
 IF actor IS NULL OR NOT private.can_access_ticket(p_ticket_id) OR
 (private.active_profile_role()<>'CONTRACTOR' AND NOT private.has_permission(actor,'admin.tickets.edit')) THEN
 RAISE EXCEPTION 'Assigned crew or authorized ticket manager access required' USING ERRCODE='42501'; END IF;
 IF p_id IS NULL OR p_kind IS NULL OR p_kind NOT IN ('NOTE','ENVIRONMENTAL','PUBLIC_SAFETY') OR p_body IS NULL OR length(btrim(p_body)) NOT BETWEEN 1 AND 4000 OR p_reported_at IS NULL THEN
 RAISE EXCEPTION 'Choose a report type and enter 1–4000 characters' USING ERRCODE='23514'; END IF;
 SELECT * INTO t FROM public.tickets WHERE id=p_ticket_id FOR UPDATE;
 SELECT * INTO n FROM public.ticket_work_notes WHERE id=p_id;
 IF FOUND THEN
  IF n.ticket_id=p_ticket_id AND n.actor_profile_id=actor AND n.kind=p_kind AND n.body=btrim(p_body) AND n.reported_at=p_reported_at THEN RETURN n; END IF;
  RAISE EXCEPTION 'This note identifier belongs to another saved record' USING ERRCODE='23514';
 END IF;
 IF t.status::text IN ('PENDING_REVIEW','APPROVED','CLOSED','ARCHIVED','EXPIRED') THEN
 RAISE EXCEPTION 'This ticket is closed for field work. Contact your team lead.' USING ERRCODE='23514'; END IF;
 INSERT INTO public.ticket_work_notes(id,ticket_id,actor_profile_id,kind,body,reported_at)
 VALUES(p_id,p_ticket_id,actor,p_kind,btrim(p_body),p_reported_at) RETURNING * INTO n;
 IF p_kind<>'NOTE' THEN
  UPDATE public.tickets SET severity='CRITICAL',is_important=true,updated_by=actor WHERE id=t.id;
  FOR recipient IN SELECT id FROM public.profiles WHERE is_active AND
   (id=t.team_lead_id OR role::text IN ('CEO','SUPER_ADMIN') AND private.has_permission(id,'admin.tickets.view')) LOOP
   PERFORM private.notify_ticket_user(recipient,t.id,
    CASE p_kind WHEN 'ENVIRONMENTAL' THEN 'Environmental escalation · ' ELSE 'Public safety escalation · ' END||t.ticket_number,
    n.body,'ticket-work-note:'||n.id||':'||recipient);
  END LOOP;
 END IF;
 INSERT INTO public.audit_logs(action,entity_type,entity_id,user_id,user_role,new_values,change_summary)
 VALUES(CASE WHEN p_kind='NOTE' THEN 'TICKET_WORK_NOTE_ADDED' ELSE 'TICKET_SAFETY_ESCALATED' END,'ticket',t.id,actor,
 private.active_profile_role()::public.user_role,jsonb_build_object('note_id',n.id,'kind',p_kind),
 CASE WHEN p_kind='NOTE' THEN 'Ticket work note added' ELSE 'Urgent ticket report saved and dispatch notified in-app' END);
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.set_ticket_disabled(p_ticket_id uuid, p_disabled boolean)
 RETURNS tickets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor uuid := (SELECT auth.uid());
  actor_role text := private.active_profile_role();
  current_ticket public.tickets%ROWTYPE;
  updated_ticket public.tickets%ROWTYPE;
BEGIN
  IF actor IS NULL
     OR actor_role NOT IN ('ADMIN', 'CEO', 'SUPER_ADMIN')
     OR NOT private.has_permission(actor, 'admin.tickets.edit') THEN
    RAISE EXCEPTION 'Ticket edit permission required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO current_ticket
  FROM public.tickets
  WHERE id = p_ticket_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found' USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(current_ticket.is_deleted, false) = p_disabled THEN
    RETURN current_ticket;
  END IF;

  UPDATE public.tickets
  SET is_deleted = p_disabled,
      deleted_at = CASE WHEN p_disabled THEN pg_catalog.now() ELSE NULL END,
      deleted_by = CASE WHEN p_disabled THEN actor ELSE NULL END,
      updated_at = pg_catalog.now(),
      updated_by = actor
  WHERE id = p_ticket_id
  RETURNING * INTO updated_ticket;

  INSERT INTO public.audit_logs(action, entity_type, entity_id, user_id, user_role, old_values, new_values, change_summary)
  VALUES (
    CASE WHEN p_disabled THEN 'TICKET_DISABLED' ELSE 'TICKET_RESTORED' END,
    'ticket',
    p_ticket_id,
    actor,
    actor_role::public.user_role,
    jsonb_build_object(
      'is_deleted', COALESCE(current_ticket.is_deleted, false),
      'deleted_at', current_ticket.deleted_at,
      'deleted_by', current_ticket.deleted_by
    ),
    jsonb_build_object(
      'is_deleted', updated_ticket.is_deleted,
      'deleted_at', updated_ticket.deleted_at,
      'deleted_by', updated_ticket.deleted_by
    ),
    CASE WHEN p_disabled
      THEN 'Ticket disabled from active lists; ticket and assessment history retained'
      ELSE 'Ticket restored to the active list'
    END
  );

  RETURN updated_ticket;
END;
$function$

CREATE OR REPLACE FUNCTION private.user_permission_settings(p_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); result jsonb;
BEGIN
 IF actor IS NULL OR NOT private.has_permission(actor,'admin.users.view') THEN RAISE EXCEPTION 'Permission denied' USING ERRCODE='42501'; END IF;
 SELECT jsonb_build_object('profile',jsonb_build_object('id',p.id,'email',p.email,'first_name',p.first_name,'last_name',p.last_name,'role',p.role,'is_active',p.is_active),
  'overrides',coalesce((SELECT jsonb_object_agg(permission_key,effect) FROM public.user_permissions WHERE profile_id=p.id),'{}'::jsonb),
  'permissions',(SELECT jsonb_object_agg(permission_key,private.has_permission(p.id,permission_key)) FROM private.permission_catalog),
  'version',(SELECT version FROM public.user_permission_versions WHERE profile_id=p.id)) INTO result FROM public.profiles p WHERE p.id=p_profile_id;
 IF result IS NULL THEN RAISE EXCEPTION 'User not found' USING ERRCODE='P0002'; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.finalize_contractor_invite(p_actor_id uuid, p_profile_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_resend boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE contractor_id uuid;
BEGIN
 IF NOT private.has_permission(p_actor_id,'admin.users.edit') THEN RAISE EXCEPTION 'Invitation permission required'; END IF;
 PERFORM 1 FROM public.profiles WHERE id=p_profile_id AND role::text='CONTRACTOR' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Contractor profile required'; END IF;
 UPDATE public.profiles SET first_name=p_first_name,last_name=p_last_name,phone=p_phone,must_reset_password=true WHERE id=p_profile_id;
 SELECT id INTO contractor_id FROM public.contractors WHERE profile_id=p_profile_id;
 IF contractor_id IS NULL THEN
  INSERT INTO public.contractors(profile_id,business_name,business_email,business_phone,onboarding_status,is_eligible_for_assignment)
  VALUES(p_profile_id,p_first_name||' '||p_last_name,p_email,p_phone,'PENDING',false) RETURNING id INTO contractor_id;
 END IF;
 INSERT INTO public.contractor_invitations(profile_id,email,first_name,last_name,invited_by,last_result)
 VALUES(p_profile_id,p_email,p_first_name,p_last_name,p_actor_id,'sent') ON CONFLICT(profile_id) DO UPDATE SET first_name=p_first_name,last_name=p_last_name,sent_at=clock_timestamp(),last_result='sent',invited_by=p_actor_id,send_count=public.contractor_invitations.send_count+1;
 INSERT INTO public.audit_logs(action,entity_type,entity_id,user_id,user_role,new_values,change_summary)
 VALUES(CASE WHEN p_resend THEN 'INVITE_RESENT' ELSE 'INVITE_SENT' END,'contractor_invitation',p_profile_id,p_actor_id,'SUPER_ADMIN',jsonb_build_object('email',p_email,'contractor_id',contractor_id,'result','sent'),'Contractor invitation sent');
 RETURN jsonb_build_object('profile_id',p_profile_id,'contractor_id',contractor_id,'email',p_email,'state','invited');
END $function$

CREATE OR REPLACE FUNCTION public.add_contractor_record(p_actor_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_terms jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c_id uuid; agreement_id uuid; actor_role public.user_role; normalized_email text:=lower(btrim(p_email));
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' THEN
  RAISE EXCEPTION 'Server-only contractor creation' USING ERRCODE='42501'; END IF;
 SELECT role INTO actor_role FROM public.profiles WHERE id=p_actor_id AND is_active AND NOT must_reset_password;
 IF actor_role IS NULL OR actor_role::text NOT IN ('CEO','SUPER_ADMIN')
 OR NOT private.has_permission(p_actor_id,'admin.contractors.edit') OR NOT private.has_permission(p_actor_id,'admin.payroll.edit') THEN
  RAISE EXCEPTION 'Privileged contractor and payroll editing required' USING ERRCODE='42501'; END IF;
 IF p_first_name IS NULL OR p_last_name IS NULL OR length(btrim(p_first_name)) NOT BETWEEN 1 AND 80 OR length(btrim(p_last_name)) NOT BETWEEN 1 AND 80
 OR normalized_email IS NULL OR length(normalized_email)>254 OR normalized_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
 OR (coalesce(p_phone,'')<>'' AND p_phone !~ '^[(][0-9]{3}[)] [0-9]{3}-[0-9]{4}$') THEN
  RAISE EXCEPTION 'Invalid contractor contact details' USING ERRCODE='23514'; END IF;
 PERFORM private.validate_compensation(p_terms);
 PERFORM pg_advisory_xact_lock(hashtextextended(normalized_email,734918206));
 IF EXISTS(SELECT 1 FROM public.profiles WHERE lower(email)=normalized_email)
 OR EXISTS(SELECT 1 FROM public.contractors WHERE lower(business_email)=normalized_email) THEN
  RAISE EXCEPTION 'A contractor or account already uses this email address' USING ERRCODE='23505'; END IF;
 INSERT INTO public.contractors(first_name,last_name,business_name,business_email,business_phone,role,onboarding_status,is_eligible_for_assignment,eligibility_reason,created_by)
 VALUES(btrim(p_first_name),btrim(p_last_name),btrim(p_first_name)||' '||btrim(p_last_name),normalized_email,nullif(p_phone,''),(p_terms->>'role')::public.contractor_role,'PENDING',false,'Onboarding approval required',p_actor_id)
 RETURNING id INTO c_id;
 INSERT INTO public.contractor_pay_agreements(contractor_id,effective_from,terms,created_by)
 VALUES(c_id,clock_timestamp(),p_terms,p_actor_id) RETURNING id INTO agreement_id;
 INSERT INTO public.audit_logs(action,entity_type,entity_id,user_id,user_role,new_values,change_summary)
 VALUES('CONTRACTOR_ADDED','contractor',c_id,p_actor_id,actor_role,jsonb_build_object('first_name',btrim(p_first_name),'last_name',btrim(p_last_name),'email',normalized_email,'onboarding_status','PENDING','agreement_id',agreement_id),'Contractor record added without an account or invitation');
 RETURN jsonb_build_object('id',c_id,'agreement_id',agreement_id,'onboarding_status','PENDING');
END $function$

CREATE OR REPLACE FUNCTION public.create_storm_event_with_rates(p_event jsonb, p_role_rates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); event_row public.storm_events; item jsonb; initial_status text;
BEGIN
 IF actor IS NULL OR NOT private.has_permission(actor,'admin.storms.edit') OR NOT private.has_permission(actor,'admin.payroll.view') OR NOT private.has_permission(actor,'admin.payroll.edit') THEN
  RAISE EXCEPTION 'Storm and payroll editing permissions are required' USING ERRCODE='42501';
 END IF;
 PERFORM private.validate_storm_role_rates(p_role_rates);
 IF jsonb_typeof(p_event) IS DISTINCT FROM 'object' OR nullif(btrim(p_event->>'event_code'),'') IS NULL
   OR nullif(btrim(p_event->>'name'),'') IS NULL OR nullif(btrim(p_event->>'utility_client'),'') IS NULL THEN
  RAISE EXCEPTION 'Storm code, name, and utility are required' USING ERRCODE='23514';
 END IF;
 initial_status:=coalesce(nullif(p_event->>'status',''),'MOB');
 IF initial_status NOT IN ('MOB','ACTIVE','DE-MOB','RELEASED','BILLING','CLOSED') THEN
  RAISE EXCEPTION 'Invalid storm status' USING ERRCODE='23514';
 END IF;
 INSERT INTO public.storm_events(event_code,name,utility_client,status,region,contract_reference,start_date,end_date,notes,created_by,updated_by)
 VALUES(upper(btrim(p_event->>'event_code')),btrim(p_event->>'name'),upper(btrim(p_event->>'utility_client')),
   CASE WHEN initial_status='CLOSED' THEN 'MOB' ELSE initial_status END,
   nullif(btrim(p_event->>'region'),''),nullif(btrim(p_event->>'contract_reference'),''),
   nullif(p_event->>'start_date','')::date,nullif(p_event->>'end_date','')::date,nullif(p_event->>'notes',''),actor,actor)
 RETURNING * INTO event_row;
 FOR item IN SELECT value FROM jsonb_array_elements(p_role_rates) LOOP
  INSERT INTO public.storm_role_pay_rates(storm_event_id,role,hourly_rate,updated_by)
   VALUES(event_row.id,(item->>'role')::public.contractor_role,(item->>'pay_rate')::numeric,actor);
  INSERT INTO public.utility_billing_rates(storm_event_id,role,work_type,hourly_rate,currency,updated_by)
   VALUES(event_row.id,(item->>'role')::public.contractor_role,NULL,(item->>'bill_rate')::numeric,'USD',actor);
 END LOOP;
 IF initial_status='CLOSED' THEN UPDATE public.storm_events SET status='CLOSED' WHERE id=event_row.id RETURNING * INTO event_row; END IF;
 RETURN to_jsonb(event_row);
END $function$
